begin;

alter table public.creator_posts add column if not exists caption text;
alter table public.creator_posts add column if not exists status text not null default 'draft' check (status in ('draft','scheduled','published','archived'));
alter table public.creator_posts add column if not exists published_at timestamptz;
alter table public.creator_posts add column if not exists scheduled_at timestamptz;
alter table public.creator_posts add column if not exists comments_enabled boolean not null default true;
alter table public.creator_posts add column if not exists sort_order integer not null default 0;

update public.creator_posts set status = case when published then 'published' else 'draft' end where status = 'draft';

create table if not exists public.media_assets (
  id uuid primary key default gen_random_uuid(),
  creator_id uuid references public.creators(id) on delete set null,
  uploaded_by uuid references auth.users(id) on delete set null,
  kind text not null check (kind in ('image','video','audio','document')),
  storage_path text not null,
  public_url text,
  thumbnail_url text,
  original_name text,
  mime_type text,
  byte_size bigint,
  width integer,
  height integer,
  duration_seconds numeric,
  status text not null default 'ready' check (status in ('uploading','ready','failed','archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists media_assets_creator_idx on public.media_assets(creator_id, created_at desc);
create index if not exists media_assets_status_idx on public.media_assets(status, created_at desc);

create table if not exists public.creator_following (
  id uuid primary key default gen_random_uuid(),
  telegram_user_id text not null,
  creator_id uuid not null references public.creators(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (telegram_user_id, creator_id)
);

create index if not exists creator_following_user_idx on public.creator_following(telegram_user_id, created_at desc);

create table if not exists public.admin_audit_log (
  id uuid primary key default gen_random_uuid(),
  admin_user_id uuid references auth.users(id) on delete set null,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists admin_audit_created_idx on public.admin_audit_log(created_at desc);

create or replace function public.set_post_publication_timestamp() returns trigger language plpgsql set search_path = public as $$
begin
  if new.status = 'published' and (old.status is distinct from 'published' or new.published_at is null) then
    new.published_at = coalesce(new.published_at, now());
    new.published = true;
  elsif new.status <> 'published' then
    new.published = false;
  end if;
  return new;
end;
$$;

drop trigger if exists creator_posts_publication_timestamp on public.creator_posts;
create trigger creator_posts_publication_timestamp before insert or update on public.creator_posts for each row execute function public.set_post_publication_timestamp();

alter table public.media_assets enable row level security;
alter table public.creator_following enable row level security;
alter table public.admin_audit_log enable row level security;

drop policy if exists media_assets_public_read on public.media_assets;
create policy media_assets_public_read on public.media_assets for select using (status = 'ready' and public_url is not null);
drop policy if exists media_assets_admin_all on public.media_assets;
create policy media_assets_admin_all on public.media_assets for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists creator_following_user_read on public.creator_following;
create policy creator_following_user_read on public.creator_following for select using (true);
drop policy if exists creator_following_user_write on public.creator_following;
create policy creator_following_user_write on public.creator_following for insert with check (true);
drop policy if exists creator_following_user_delete on public.creator_following;
create policy creator_following_user_delete on public.creator_following for delete using (true);

drop policy if exists admin_audit_admin_read on public.admin_audit_log;
create policy admin_audit_admin_read on public.admin_audit_log for select using (public.is_admin());
drop policy if exists admin_audit_admin_insert on public.admin_audit_log;
create policy admin_audit_admin_insert on public.admin_audit_log for insert with check (public.is_admin());

commit;
